package co.fcv.citas.appointment;
import java.util.Map; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import org.springframework.security.core.Authentication;
@RestController @RequestMapping("/api/v1/me/appointments") public class PatientAppointmentController { private final JdbcTemplate db; public PatientAppointmentController(JdbcTemplate db){this.db=db;}
 @PatchMapping("/{id}/cancel") @Transactional ResponseEntity<?> cancel(@PathVariable long id, Authentication a){long user=Long.parseLong(a.getName()); int n=db.update("UPDATE appointments SET status_id=(SELECT id FROM appointment_statuses WHERE code='CANCELLED'),updated_at=CURRENT_TIMESTAMP WHERE id=? AND patient_user_id=? AND scheduled_start_at>NOW() AND status_id IN (SELECT id FROM appointment_statuses WHERE code IN ('APPROVED','REQUESTED'))",id,user); if(n==0)return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("message","La cita no puede cancelarse")); db.update("UPDATE professional_slots SET appointment_id=NULL WHERE appointment_id=?",id); return ResponseEntity.ok(Map.of("id",id,"status","CANCELLED")); }
}
